(function ($, window, document) {
    console.log("init");

    // Define an object 'o' with methods for various functionalities
    var o = {
        init: function () {
            o.select2();
            o.stellar();
            o.carousel();
            o.portfolio();
            o.lightCase();
            o.sideNav();
            o.counter();
            o.skills();
            o.aos();
            o.navbarChange();
        },

        // Initialize Select2 for styling dropdowns
        select2: function () {
            $(document).ready(function () {
                $("select").select2();
            });
        },

        // Initialize Stellar.js for parallax effects
        stellar: function () {
            var screenWidth = $(window).width();
            if (screenWidth >= 767) {
                $(".bg-fixed").attr("data-stellar-background-ratio", "0.8");
                $.stellar({
                    horizontalScrolling: false,
                    responsive: true,
                    parallaxBackgrounds: true,
                    scrollProperty: "scroll",
                });
            }
        },

        // Initialize carousels using Owl Carousel
        carousel: function () {
            $(".testi-carousel").owlCarousel({
                loop: true,
                margin: 10,
                autoplay: true,
                nav: false,
                dots: true,
                dotSpeed: 1000,
                autoplaySpeed: 1000,
                items: 1,
            });

            $(".client-slider").owlCarousel({
                loop: true,
                margin: 10,
                nav: true,
                navSpeed: 1000,
                dots: false,
                autoplay: true,
                autoplaySpeed: 1000,
                navText: [
                    '<span class="fa fa-angle-left"></span>',
                    '<span class="fa fa-angle-right"></span>',
                ],
                responsive: {
                    0: { items: 1 },
                    600: { items: 3 },
                    1000: { items: 6 },
                },
            });
        },

        // Initialize Isotope for portfolio filtering
        portfolio: function () {
            var grid = $(".grid-portfolio").isotope({
                itemSelector: ".grid-item",
                masonry: {
                    gutter: ".gutter-sizer",
                    columnWidth: ".grid-sizer",
                },
                percentPosition: true,
            });

            $(".filter-button-group").on("click", "a", function () {
                var filterValue = $(this).attr("data-filter");
                grid.isotope({ filter: filterValue });
            });

            $(".btn-filter a.is-checked").addClass("active");
            $(".btn-filter a").on("click", function () {
                $(".btn-filter a").removeClass("active");
                $(this).addClass("active");
            });
        },

        // Initialize Lightcase for lightbox functionality
        lightCase: function () {
            $(document).ready(function () {
                $("a[data-rel^=lightcase]").lightcase();
            });
        },

        // Handle side navigation and search toggles
        sideNav: function () {
            $("#side-nav-open").click(function () {
                $("#side-nav").css("width", "300px");
                setTimeout(() => $("body").addClass("sidenav-open"), 200);
                setTimeout(() => $("body").addClass("in"), 400);
            });

            $("#side-nav-close, #canvas-overlay").click(function () {
                setTimeout(() => $("body").removeClass("in"), 200);
                setTimeout(() => {
                    $("body").removeClass("sidenav-open");
                    $("#side-nav").css("width", "0");
                }, 400);
            });

            $("#side-search-open").click(function () {
                $("#side-search").css("width", "300px");
                setTimeout(() => $("body").addClass("sidesearch-open"), 200);
                setTimeout(() => $("body").addClass("in"), 300);
            });

            $("#side-search-close, #canvas-overlay").click(function () {
                setTimeout(() => $("body").removeClass("in"), 200);
                setTimeout(() => {
                    $("body").removeClass("sidesearch-open");
                    $("#side-search").css("width", "0");
                }, 300);
            });
        },

        // Initialize counter animations using Waypoints
        counter: function () {
            $("#counter").each(function () {
                $(this).waypoint({
                    handler: function () {
                        $(".number").countTo({ speed: 1000 });
                        this.destroy();
                    },
                    offset: "80%",
                });
            });
        },

        // Animate skill progress bars
        skills: function () {
            $("#skills").each(function () {
                $(this).waypoint({
                    handler: function () {
                        $(".progress").each(function () {
                            var percent = $(this).attr("data-percent");
                            console.log(percent);
                            $(this).find(".progress-bar").delay(10000).css({ width: percent });
                        });
                    },
                    offset: "80%",
                });
            });
        },

        // Initialize AOS (Animate On Scroll)
        aos: function () {
            AOS.init({ once: true });
        },

        // Change navbar style on scroll
        navbarChange: function () {
            $(window).scroll(function () {
                var scrollTop = $(window).scrollTop();
                if (scrollTop > 150) {
                    $("#header-navbar").removeClass("navbar-transparent");
                    $("body").addClass("not-on-top");
                } else {
                    $("body").removeClass("not-on-top");
                    $("#header-navbar").addClass("navbar-transparent");
                }
            });
        },
    };

    // Initialize all features when the document is ready
    $(document).ready(function () {
        o.init();
    });
})(window.jQuery, window, document);
